function deleteform(string $target,string $id):void {echo '<form method="post" action="'.linkto('admin').'" onsubmit="return confirm(\'Permanently delete this item?\')">';posthidden('delete');echo '<input type="hidden" name="target" value="'.h($target).'"><input type="hidden" name="id" value="'.h($id).'"><input type="hidden" name="tab" value="'.h($target).'"><button class="delete-btn">Delete</button></form>';}